#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countScaledShadowPairs(std::vector<int>& nums, int k) {
        std::unordered_map<long long, int> freq;
        long long pairs = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            long long key = (long long)nums[i] - (long long)k * i;
            pairs += freq[key];
            freq[key]++;
        }
        return pairs;
    }
};

import java.util.*;

class Solution {
    public long countScaledShadowPairs(int[] nums, int k) {
        Map<Long, Integer> freq = new HashMap<>();
        long pairs = 0;
        for (int i = 0; i < nums.length; i++) {
            long key = (long) nums[i] - (long) k * i;
            pairs += freq.getOrDefault(key, 0);
            freq.put(key, freq.getOrDefault(key, 0) + 1);
        }
        return pairs;
    }
}

